import{_ as a,o as i,c as s,ae as n}from"./chunks/framework.EHGTsUvI.js";const b=JSON.parse('{"title":"Roles & Permissions","description":"","frontmatter":{"title":"Roles & Permissions"},"headers":[],"relativePath":"Main/Main/Company/permissions.md","filePath":"Main/Main/Company/permissions.md"}'),r={name:"Main/Main/Company/permissions.md"};function o(t,e,l,m,p,d){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="roles-permissions" tabindex="-1">Roles &amp; Permissions <a class="header-anchor" href="#roles-permissions" aria-label="Permalink to &quot;Roles &amp; Permissions&quot;">​</a></h1><p>Company Roles &amp; Permissions determine what each member of a Company is allowed to do.</p><p>The Company Owner can assign members different roles, allowing responsibilities to be shared between trusted members.</p><h2 id="company-roles" tabindex="-1">Company Roles <a class="header-anchor" href="#company-roles" aria-label="Permalink to &quot;Company Roles&quot;">​</a></h2><p>Each Company member has a role that determines their available permissions.</p><table tabindex="0"><thead><tr><th>Role</th><th>Description</th></tr></thead><tbody><tr><td>Owner</td><td>The player who created the Company and has full control.</td></tr><tr><td>Manager</td><td>A trusted member who can manage parts of the Company.</td></tr><tr><td>Member</td><td>A standard Company member who can participate in Company activities.</td></tr></tbody></table><blockquote><p><strong>Note:</strong> The available roles and permissions may change as the Company system is updated.</p></blockquote><h2 id="owner" tabindex="-1">Owner <a class="header-anchor" href="#owner" aria-label="Permalink to &quot;Owner&quot;">​</a></h2><p>The <strong>Owner</strong> is the player who created the Company.</p><p>The Owner has the highest level of access and is responsible for managing the Company.</p><h3 id="owner-permissions" tabindex="-1">Owner Permissions <a class="header-anchor" href="#owner-permissions" aria-label="Permalink to &quot;Owner Permissions&quot;">​</a></h3><p>The Owner can:</p><ul><li>Manage Company members</li><li>Assign Company roles</li><li>Change member permissions</li><li>Manage Company settings</li><li>Manage Company Orders</li><li>Manage Company activities</li><li>Remove members from the Company</li></ul><p>The Owner should only give management permissions to trusted members.</p><h2 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h2><p>Admins are trusted Company members who can assist the Owner with running the Company.</p><h3 id="admin-permissions" tabindex="-1">Admin Permissions <a class="header-anchor" href="#admin-permissions" aria-label="Permalink to &quot;Admin Permissions&quot;">​</a></h3><p>Admins may be able to:</p><ul><li>Manage Company members</li><li>Assist with Company Orders</li><li>Manage Company activities</li><li>Help organise Company resources</li><li>Perform other tasks granted by the Owner</li></ul><h2 id="member" tabindex="-1">Member <a class="header-anchor" href="#member" aria-label="Permalink to &quot;Member&quot;">​</a></h2><p>Members are standard Company players.</p><p>They can participate in Company activities without having full management access.</p><h3 id="member-permissions" tabindex="-1">Member Permissions <a class="header-anchor" href="#member-permissions" aria-label="Permalink to &quot;Member Permissions&quot;">​</a></h3><p>Members can generally:</p><ul><li>View Company information</li><li>View available Orders</li><li>Gather Materials</li><li>Complete Company tasks</li><li>Prepare Shipments</li><li>Contribute towards Company progression</li><li>Earn Company rewards</li></ul><p>Members cannot normally change important Company settings or manage other members unless additional permissions are granted.</p><h2 id="managing-permissions" tabindex="-1">Managing Permissions <a class="header-anchor" href="#managing-permissions" aria-label="Permalink to &quot;Managing Permissions&quot;">​</a></h2><p>Company permissions should be assigned carefully.</p><p>Giving a player additional permissions allows them to perform Company management tasks that are not available to standard members.</p><p>The Owner should consider giving management permissions only to players they trust.</p><h2 id="roles-company-progression" tabindex="-1">Roles &amp; Company Progression <a class="header-anchor" href="#roles-company-progression" aria-label="Permalink to &quot;Roles &amp; Company Progression&quot;">​</a></h2><p>Company roles do not prevent members from contributing to Company progression.</p><p>All members can contribute by participating in Company activities such as:</p><ul><li>Completing Orders</li><li>Gathering Materials</li><li>Preparing Shipments</li><li>Using Company equipment</li><li>Working towards seasonal progression</li></ul><h2 id="useful-tips" tabindex="-1">Useful Tips <a class="header-anchor" href="#useful-tips" aria-label="Permalink to &quot;Useful Tips&quot;">​</a></h2><ul><li>Only give management permissions to trusted members.</li><li>Use roles to divide responsibilities between Company members.</li><li>Keep standard members on the lowest required permission level.</li><li>Review Company members regularly.</li><li>Remove inactive members when necessary.</li><li>Make sure members understand what their role allows them to do.</li><li>Use trusted Managers to help run larger Companies.</li></ul><blockquote><p><strong>Note:</strong> Company roles and permissions may be changed or expanded in future Seasons.</p></blockquote>',37)])])}const c=a(r,[["render",o]]);export{b as __pageData,c as default};
